package main

import (
	"fmt"
	"net/http"
	"os"
)

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "8080" }
	http.HandleFunc("/", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		fmt.Fprintln(w, "<!doctype html><html><meta charset='utf-8'><title>Go workspace</title><body><h1>Hello from Jahaziel</h1><p>Edit main.go and reload this preview.</p></body></html>")
	})
	address := ":" + port
	fmt.Println("Listening on 0.0.0.0" + address)
	if err := http.ListenAndServe("0.0.0.0"+address, nil); err != nil { panic(err) }
}
